var i=273;var a=`273-batch-scaling-and-yield-adjustment`;var n=`262`;var o={en:`Batch Scaling and Yield Adjustment`,ua:`Масштабування рецептур та коригування виходу`};var s={short:`Scaling changes the quantity of food while preserving intended proportions, texture, and safety. Ingredient arithmetic is only the first step; vessel geometry, heat transfer, evaporation, and equipment capacity must also be tested.`,sections:[{title:`Core idea`,text:`Calculate a scaling factor as target yield divided by original yield, using matching units and the same stage of production. Distinguish raw purchased weight, trimmed usable weight, and cooked served weight.`},{title:`Scientific / practical principles`,text:`Surface area does not grow at the same rate as volume. Larger soup pots heat and cool differently, crowded pans brown less effectively, and large baking batches may need different pans, mixing, or time.`},{title:`How to apply it`,text:`Record yield and portion size; multiply ingredient masses by the factor, then recalculate edible yields and round only where practical. Confirm vessel capacity, mixing limits, holding and cooling plans, and retest seasoning and consistency.`},{title:`Practical example`,text:`A recipe yields 8 portions of 250 g each, or 2 kg. For 20 portions, the mass target is 5 kg and the scaling factor is 2.5; ingredients scale by 2.5 initially, but pan size and cooking schedule require review.`},{title:`Common mistakes and limitations`,text:`Do not multiply oven time by 2.5. Seasoning and leavening can respond nonlinearly; food safety controls cannot be waived for a larger quantity.`},{title:`Related theories`,text:`007, 105, 191, 266, 270, 279, 282.`},{title:`Hands-on exercise`,text:`A 6-portion recipe uses 900 g edible vegetables; plan 24 portions at 75% edible yield. The target edible mass is 3,600 g and the theoretical as-purchased mass is 4,800 g. Then check whether pans and safe cooling capacity support this batch.`}]};var r={short:`Масштабування змінює кількість страви зі збереженням задуманої текстури, пропорцій та безпеки. Перерахунок інгредієнтів є лише початком: потрібно врахувати розміри посуду, теплопередачу, випаровування й потужність обладнання.`,sections:[{title:`Головна ідея`,text:`Коефіцієнт масштабування дорівнює бажаному виходу, поділеному на початковий, за однакових одиниць і стадій обробки. Розрізняйте закуплену масу, їстівну після очищення та готову масу порцій.`},{title:`Наукові та практичні принципи`,text:`Площа поверхні й об’єм збільшуються по-різному. У великій каструлі змінюється нагрівання та охолодження, переповнена сковорода гірше підрум’янює, а велика партія випічки потребує іншої організації процесу.`},{title:`Як застосовувати`,text:`Запишіть вихід і масу порції, помножте маси інгредієнтів на коефіцієнт, потім уточніть втрати й округлення. Перевірте місткість посуду, план охолодження, час, приправи та консистенцію.`},{title:`Практичний приклад`,text:`Рецепт дає 8 порцій по 250 г, тобто 2 кг. Для 20 порцій потрібно 5 кг, а коефіцієнт дорівнює 2,5. Маси інгредієнтів спершу збільшують у 2,5 раза, але метод приготування перевіряють окремо.`},{title:`Поширені помилки та обмеження`,text:`Не множте час випікання на 2,5. Сіль, розпушувачі та випаровування інколи потребують додаткової корекції; збільшення партії не скасовує вимог безпеки.`},{title:`Пов’язані теорії`,text:`007, 105, 191, 266, 270, 279, 282.`},{title:`Практична вправа`,text:`Рецепт на 6 порцій потребує 900 г очищених овочів. Сплануйте 24 порції за виходу їстівної частини 75%: потрібно 3 600 г їстівної маси, або теоретично 4 800 г закупленої сировини. Перевірте місткість посуду й можливість безпечного охолодження.`}]};var l=[7,105,191,266,270,279,282];var d=`Sources / Джерела`;var c=[`https://foodbuyingguide.fns.usda.gov/Home/About`,`https://www.fda.gov/food/retail-food-protection/fda-food-code`,`https://www.kingarthurbaking.com/pro/reference/bakers-percentage`,`https://www.kingarthurbaking.com/blog/2020/11/23/how-to-reduce-a-recipe`];var g={id:273,slug:a,group:`262`,title:o,en:s,ua:r,related:l,referenceTitle:d,references:c};export{g as default,s as en,n as group,i as id,d as referenceTitle,c as references,l as related,a as slug,o as title,r as ua};